  // out of the fit: it is what the tile is framed against
  m.traverse((o) => { if (o.userData.bwKeepHidden) o.visible = false; else o.visible = true; });
  m.position.set(0, 0, 0); m.rotation.set(0, 0, 0); m.scale.setScalar(1);
  iconFit.clear();
