    const ang = 0.5 * Math.atan2(2 * sxy, sxx - syy);
    const tr = sxx + syy, det = Math.sqrt(Math.max(0, (sxx - syy) * (sxx - syy) * 0.25 + sxy * sxy));
    const l1 = tr * 0.5 + det, l2 = Math.max(1e-6, tr * 0.5 - det);
