    ud.rig.scale.set(1 + 0.34 * (1 - e), 1 - 0.42 * (1 - e), 1 + 0.34 * (1 - e));
    ud.rig.rotation.x = 0.55 * (1 - e);
    ud.rig.rotation.z = 0.22 * (1 - e);
