    if (!u.called && dist > (performance.now() < chaseGraceUntil ? Math.min(u.wake, CHASE_GRACE_R) : u.wake)) return;
    if (settings.devMode) return;        // DEV MODE: they stay where they were put
    u.st.awake = true;
