  sg.gain.exponentialRampToValueAtTime(0.09, t + 0.06);
  sg.gain.exponentialRampToValueAtTime(0.0001, t + 0.4);
  spray.connect(hp).connect(sg).connect(out);
  spray.start(t + 0.02); spray.stop(t + 0.44);

