  const t = ctx.currentTime;
  const rasp = noiseBurst(CRAB_WIND, (x) => (0.35 + 0.65 * Math.random()) * Math.min(1, x * 3.5) * (1 - x * 0.25));
  const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 3.2;
