  // the standing water's ripples creep along the channel toward the sea
  const wm = drainTunnel.userData.waterMat;
  if (wm && wm.normalMap) { wm.normalMap.offset.x -= dt * 0.03; wm.normalMap.offset.y += dt * 0.011; }
