  if (ctx.createStereoPanner) {
    const sp = ctx.createStereoPanner();
    sp.pan.value = THREE.MathUtils.clamp(pan, -1, 1);
    sp.connect(drainAudio.gain);
    out = sp;
    setTimeout(() => { try { sp.disconnect(); } catch (e) {} }, 2800);
  }
