  const f = 480 + Math.random() * 760;
  const o = ctx.createOscillator(); o.type = 'sine';
  o.frequency.setValueAtTime(f * 0.5, t);
  o.frequency.exponentialRampToValueAtTime(f * 1.95, t + 0.038);
