  g.fillStyle = '#8a9aa8'; g.fillRect(17, 14, 16, 22);
  g.fillStyle = '#2c3a44'; g.fillRect(20, 17, 10, 16);
  g.fillStyle = '#c8a24a'; g.fillRect(23, 24, 4, 7);
  g.fillStyle = '#5a4a34'; g.fillRect(16, 36, 18, 6);
