    for (let a = 0; a <= 6.2832; a += 0.08) { const r = R * (0.82 + artFbm(nz2, Math.cos(a) * 2 + i * 7, Math.sin(a) * 2, 3) * 0.4); pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]); }
    g.beginPath(); pts.forEach(([x, y], k) => (k ? g.lineTo(x, y) : g.moveTo(x, y))); g.closePath();
