    g.font = `${opts.caps ? '' : 'italic '}${size}px ${FONT}`; g.textAlign = opts.align || 'left'; g.textBaseline = 'middle';
    if ('letterSpacing' in g) g.letterSpacing = opts.caps ? `${Math.round(size * 0.18)}px` : '0.5px';
