  g.beginPath(); cliff.forEach(([x, y], i) => (i ? g.lineTo(x + 16, y) : g.moveTo(x + 16, y))); g.strokeStyle = 'rgba(120,92,52,0.18)'; g.lineWidth = 30; g.stroke();
