  const meshes = [];
  g.userData.bunker.root.traverse((o) => { if (o.isMesh && o.name !== 'hitProxy') meshes.push(o); });
  // the desk is ours now: the shelf the bar lies on is the rebuilt one
  if (workTable) workTable.traverse((o) => { if (o.isMesh) meshes.push(o); });
