      let ux = cp.x - c.x, uz = cp.z - c.z; const ul = Math.hypot(ux, uz) || 1; ux /= ul; uz /= ul;
      const tx = cp.x + ux * 0.95, tz = cp.z + uz * 0.95;      // behind it, from where you are
