          const ax = c.x + (Math.random() - 0.5) * 1.6 - ux * (0.4 + Math.random() * 1.2), az = c.z + (Math.random() - 0.5) * 1.6 - uz * (0.4 + Math.random() * 1.2);
          G.vel.set((ax - gp.x) / T, (BUNKER_Y + 0.1 - gp.y + 0.5 * 15 * T * T) / T, (az - gp.z) / T);
