    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 300; bp.Q.value = 1.1;
    bp.frequency.setValueAtTime(520, t); bp.frequency.exponentialRampToValueAtTime(190, t + 0.20);
