    g.strokeStyle = r() < 0.5 ? `rgba(255,255,255,${0.15 + r() * 0.25})` : `rgba(60,40,20,${0.08 + r() * 0.12})`;
    g.beginPath(); g.moveTo(x, y); g.lineTo(x + (r() - 0.5) * 3, y + l); g.stroke();
