  const waterMat = () => new THREE.MeshStandardMaterial({ color: 0x3b5668, roughness: 0.40,
    metalness: 0.0, transparent: true, opacity: 0.78, depthWrite: false,
    emissive: new THREE.Color(0x4a6d84), emissiveIntensity: 1.25 });
