    g.moveTo(x, y);
    g.quadraticCurveTo(x + Math.cos(a) * len * 0.5 + (rnd() - 0.5) * 22,
                       y + Math.sin(a) * len * 0.5 + (rnd() - 0.5) * 22,
                       x + Math.cos(a) * len, y + Math.sin(a) * len);
    g.stroke();
