    const f = dojoFloorAt(b.p.x, b.p.z, b.p.y + 0.2);
    if (f !== null && b.p.y < f + 0.03) { shurDrop(b, true); continue; }
    const e = camera.position;
    const dy = THREE.MathUtils.clamp(b.p.y, e.y - playerHeight() * 0.85, e.y + 0.12);
