  shaft.position.copy(thr); shaft.rotation.x = 0.62; shaft.frustumCulled = false; shaft.raycast = () => {}; shaft.userData.bwGhost = true; shaft.renderOrder = 7;
  G.add(shaft);
  // the way back up: a proxy at the foot of the throat
