  F.motes.material.uniforms.uPx.value = px; F.spray.material.uniforms.uPx.value = px;
  const pa = F.spray.geometry.attributes.position, aa = F.spray.geometry.attributes.aA, as = F.spray.geometry.attributes.aS;
  let any = false;
