    const P = F.WK[F.wNext]; F.wNext = (F.wNext + 1) % F.WK.length;
    const a = Math.random() * Math.PI * 2, r = spread * Math.sqrt(Math.random());
    P.p.set(x + Math.cos(a) * r, -0.25 + Math.random() * 0.15, z + Math.sin(a) * r);
