  const t = ctx.currentTime, d = Math.hypot(x - camera.position.x, z - camera.position.z), k = 1 / (1 + d / 18);
  const n = noiseBurst(dur, (u) => Math.sin(Math.PI * u) * (0.55 + 0.45 * Math.sin(u * dur * 4.6)) * (0.7 + 0.3 * Math.random()));
