const COMFY_HEAR = 11, COMFY_HEAR_RUN = 22, COMFY_HEAR_CROUCH = 5;
const COMFY_SEE = 44, COMFY_SEE_BUSY = 36, COMFY_WATCH = 58;
const COMFY_CONE = -0.1;          // a little more than the half of the world in front of it
