    const x0 = 128 + Math.cos(a) * 58, y0 = 124 + Math.sin(a) * 36;
    const x1 = 128 + Math.cos(a) * (58 + len), y1 = 124 + Math.sin(a) * (36 + len * 0.5);
    const gr = g.createLinearGradient(x0, y0, x1, y1);
