    m: Array.from({ length: C13_MOTE }, () => ({ life: 0, max: 1, x: 0, y: 0, z: 0, ph: 0, s: 0 })),
    q: Array.from({ length: C13_MIST }, () => ({ life: 0, max: 1, x: 0, y: 0, z: 0, s: 0, a: 0 })),
    si: 0, ei: 0, sAcc: 0, eAcc: 0,
