    q.vx = (r() - 0.5) * 0.15; q.vy = (F.big ? 0.9 : 0.4) + r() * 0.3; q.vz = (r() - 0.5) * 0.15;
    q.max = q.life = (F.big ? 6 : 2.4) + r() * 3; q.s0 = F.big ? 0.5 : 0.15; q.s1 = (F.big ? 3.4 : 0.9) + r() * 1.2; q.a = F.big ? 0.5 : 0.22;
