  if (!inC13) {
    if (c13Snd) { const t = ctx.currentTime; c13Snd.lute.gain.setTargetAtTime(0, t, 0.4); if (c13Snd.fg) c13Snd.fg.gain.setTargetAtTime(0, t, 0.4); c13Snd.playing = false; }
    return;
  }
