    const upright = sz.y > 0.25 && sz.y > Math.max(sz.x, sz.z) * 1.6;
    tavThrow(m, c, gy, kick, dx, dz, THREE.MathUtils.clamp((c.y - gy) / 1.0, 0, 1), upright ? 0 : 0.03, upright);
    const gb = gibs[gibs.length - 1]; gb.onLand = thrKnock; gb.life = 240;
