  const S = FARM_SPINE, L = [];
  let tot = 0; for (let i = 1; i < S.length; i++) { const l = Math.hypot(S[i][0] - S[i - 1][0], S[i][1] - S[i - 1][1]); L.push(l); tot += l; }
  let d = t * tot;
