  for (let r = 0; r * 0.27 + 0.2 < LH; r++) { const s = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, 0.44, 5), ironDark); s.rotation.z = Math.PI / 2; s.position.set(0, 0.2 + r * 0.27, 0); ladder.add(s); }
