  for (let i = 0; i < 8; i++) { const a = (i / 8) * Math.PI * 2 + 0.2; const b = new THREE.BoxGeometry(0.06, 0.5, 0.6); b.rotateY(a); b.translate(ISLE_AXIS.x + Math.sin(a) * 2.25, y - 0.28, ISLE_AXIS.z + Math.cos(a) * 2.25); iron.push(b); }
