  const blur = 16 * (1 - 0.3 * ease(2, T.lift0) - 0.32 * lift) * (1 - ease(T.left0 + 0.4, T.left1 + 0.6));
  const glare = 1.0 + 0.55 * (1 - ease(0.5, T.lift1)) + 0.12 * (1 - ease(T.lift1, T.left1));
