  playSampleAt('doorClose', p.x, p.z, { gain: hard ? 1.4 : 1.0, rate: 0.82, ref: 8, far: 50, delay: 0.1 + Math.random() * 0.05 });
  sfxPlankKnock(p.x, p.z, hard ? 8 : 5);
