  const pool = FARM_TAUNTS.filter((c) => u.clips[c]);
  if (!pool.length) return false;
  const c = (u.clips[u.kind.anim.roar] && Math.random() < 0.45) ? u.kind.anim.roar : pool[(Math.random() * pool.length) | 0];
  const r = rate || (0.92 + Math.random() * 0.3);
