  deepLock = true; deepNoHands = true; deepRodOn = true; deepBend = 0;
  deep.ph = 'hook'; deep.t = 0; deep.under = false; deep.yank = 0; deep.jerkT = 0.5; deep.muffled = false; deep.hint = false;
  deep.hookP.copy(rod.pos);
  rodWhirStop();
